B.Vg=new A.dH(2,"Tr\u1ed1ng \u0111\u1ed3ng \u0110\xf4ng S\u01a1n",B.a4S,"assets/bieu-tuong-thang/02-trong-dong.png")
B.a_x=new A.cs("Chim L\u1ea1c thu\u1ed9c v\u1ec1 bi\u1ec3u t\u01b0\u1ee3ng quan tr\u1ecdng v\xec \u1edf nh\u1eefng lo\u1ea1i tr\u1ed1ng \u0111\xe3 gi\u1ea3n \u01b0\u1edbc r\u1ea5t nhi\u1ec1u h\xecnh \u1ea3nh kh\xe1c th\xec h\xecnh \u1ea3nh n\xe0y v\u1eabn xu\u1ea5t hi\u1ec7n b\xean c\u1ea1nh M\u1eb7t tr\u1eddi v\xe0 li\xean h\u1ed9i v\u1edbi m\u1ed9t lo\xe0i h\u1eadu \u0111i\u1ec3u, h\u1eadu l\xe0 kh\xed h\u1eadu, th\u1eddi ti\u1ebft, \u0111i\u1ec3u l\xe0 chim, h\u1eadu \u0111i\u1ec3u l\xe0 chim di c\u01b0 theo m\xf9a \u0111\u1ec3 s\xe1ng t\u1ea1o ra c\xe1ch g\u1ecdi t\u01b0\u01a1ng \u1ee9ng. V\u1edbi t\u01b0 c\xe1ch l\xe0 m\u1ed9t bi\u1ec3u t\u01b0\u1ee3ng, chim L\u1ea1c v\u1eeba g\u1ea7n g\u0169i th\xe2n quen v\u1eeba thi\xeang li\xeang. Chim L\u1ea1c v\u01b0\u01a1n l\xean v\u1edbi cao r\u1ed9ng nh\u01b0 kh\xe1t v\u1ecdng chinh ph\u1ee5c b\u1ea7u tr\u1eddi. Chim L\u1ea1c t\u01b0\u1ee3ng tr\u01b0ng cho \u01b0\u1edbc m\u01a1 v\u01b0\u1ee3t kh\xf4ng gian b\u1ea5t ch\u1ea5p gi\xf4ng t\u1ed1 th\u1eed th\xe1ch. Chim l\u1ea1c t\u01b0\u1ee3ng tr\u01b0ng cho tinh th\u1ea7n v\xe0 c\u1ea3 v\u0103n h\xf3a thu\u1ea7n Vi\u1ec7t, c\u0169ng l\xe0 ti\u1ec1n th\xe2n c\u1ee7a h\xecnh t\u01b0\u1ee3ng ph\u01b0\u1ee3ng ho\xe0ng \u1edf nh\u1eefng th\u1eddi \u0111\u1ea1i sau n\xe0y.",B.bf)
B.a4s=s([B.a_x],t.Xn)
B.Vo=new A.dH(3,"Chim L\u1ea1c",B.a4s,"assets/bieu-tuong-thang/03-chim-lac.png")
B.a_H=new A.cs("Bi\u1ec3u t\u01b0\u1ee3ng c\u1ee7a s\u1ee9c s\u1ed1ng v\xe0 s\u1ef1 ki\xean c\u01b0\u1eddng trong v\u0103n h\xf3a Vi\u1ec7t Nam.",B.bf)
B.a_u=new A.cs("Bi\u1ec3u t\u01b0\u1ee3ng c\u1ee7a b\u1ea3n l\u0129nh qu\u1eadt c\u01b0\u1eddng v\xe0 \xfd ch\xed b\u1ea5t khu\u1ea5t c\u1ee7a con ng\u01b0\u1eddi Vi\u1ec7t Nam",B.bf)
B.a_s=new A.cs("Bi\u1ec3u t\u01b0\u1ee3ng cho ph\u1ea9m ch\u1ea5t \u0111\u1eb7c s\u1eafc nh\u1ea5t c\u1ee7a con ng\u01b0\u1eddi Vi\u1ec7t Nam ta: \u0111o\xe0n k\u1ebft, th\u1ee7y chung, thanh cao, b\u1ea5t khu\u1ea5t.",B.bf)
B.a_n=new A.cs("Bi\u1ec3u t\u01b0\u1ee3ng c\u1ee7a m\u1eabu ng\u01b0\u1eddi qu\xe2n t\u1eed: tr\u1ecdng ch\u1eef t\xedn v\xe0 \u0111\u1ea1o ngh\u0129a. V\u1eefng ch\u1eafc v\xe0 linh ho\u1ea1t, c\u01b0\u01a1ng v\xe0 nhu l\xe0 hai m\u1eb7t c\xf3 m\u1ed1i quan h\u1ec7 bi\u1ec7n ch\u1ee9ng. N\u1ebfu ch\u1ec9 uy\u1ec3n chuy\u1ec3n m\xe0 kh\xf4ng v\u1eefng \u0111\u01b0\u1ee3c \u1edf g\u1ed1c, th\xec khi gi\xf3 b\xe3o s\u1ebd b\u1ecb lay \u0111\u1ed5, b\u1eadt g\u1ed1c. C\xf2n n\u1ebfu ch\u1ec9 ch\u1eafc \u1edf g\u1ed1c r\u1ec5 m\xe0 kh\xf4ng bi\u1ebft linh ho\u1ea1t l\u1ef1a th\u1ebf, th\xec th\xe2n s\u1ebd g\xe3y, c\xe0nh s\u1ebd l\xeca. Tre m\u1ecdc th\u1eb3ng, nh\u01b0ng d\xe1ng m\u1ec1m, gi\xf3 t\xe1p t\u1ee9 ph\xeda m\xe0 kh\xf4ng \u0111\u1ed5 g\xe3y. Tre c\u0169ng gi\u1ed1ng nh\u01b0 ng\u01b0\u1eddi qu\xe2n t\u1eed kh\xf4ng h\u1ea1 m\xecnh, m\xe0 bi\u1ebft nh\xfan nh\u01b0\u1eddng; ng\u01b0\u1eddi qu\xe2n t\u1eed ch\xednh tr\u1ef1c, m\xe0 c\u0169ng dung h\xf2a v\xec \u0111\u1ea1i c\u1ee5c.",B.bf)
B.a5v=s([B.a_H,B.a_u,B.a_s,B.a_n],t.Xn)
B.Vj=new A.dH(4,"C\xe2y tre",B.a5v,"assets/bieu-tuong-thang/04-cay-tre.jpg")
B.a_o=new A.cs("Bi\u1ec3u t\u01b0\u1ee3ng c\u1ee7a s\u1ef1 thanh cao v\xe0 tinh khi\u1ebft trong v\u0103n h\xf3a Vi\u1ec7t Nam.",B.cf)
B.a_S=new A.cs("Bi\u1ec3u t\u01b0\u1ee3ng cho s\u1ef1 b\u1ea5t khu\u1ea5t c\u1ee7a qu\xe2n t\u1eed, gi\u1eef ch\u1eb7t l\xf2ng m\xecnh tr\u01b0\u1edbc c\xe1m d\u1ed7 l\u1ee3i danh, gi\u1eef cho m\xecnh s\u1ef1 trong s\u1ea1ch gi\u1eefa ch\u1ed1n b\xf9n nh\u01a1.",B.cf)
B.a5l=s([B.a_o,B.a_S],t.Xn)
B.Vn=new A.dH(5,"Hoa sen",B.a5l,"assets/bieu-tuong-thang/05-hoa-sen.jpg")
B.a_I=new A.cs("H\xecnh \u1ea3nh c\u1ee7a r\u1ed3ng g\u1eafn li\u1ec1n v\u1edbi b\u1eadc \u0111\u1ebf v\u01b0\u01a1ng, th\u1ec3 hi\u1ec7n quy\u1ec1n uy, mang n\u0103ng l\u1ef1c t\xe2m linh si\xeau nhi\xean. \u1ea4n t\xedn c\u1ee7a vua ch\xfaa \u0111\u01b0\u1ee3c ch\u1ea1m kh\u1eafc h\xecnh t\u01b0\u1ee3ng r\u1ed3ng v\xe0ng, bi\u1ec3u tr\u01b0ng cho s\u1ee9c m\u1ea1nh v\xe0 s\u1ef1 uy quy\u1ec1n c\u1ee7a b\u1eadc \u0111\u1ebf v\u01b0\u01a1ng, ng\u01b0\u1eddi \u0111\u1ee9ng \u0111\u1ea7u. H\xecnh r\u1ed3ng tr\xean ho\xe0ng b\xe0o, \u0111\u1ed3 d\xf9ng c\u1ee7a vua, ch\u1ec9 c\xf3 vua m\u1edbi \u0111\u01b0\u1ee3c s\u1eed d\u1ee5ng h\xecnh t\u01b0\u1ee3ng n\xe0y \u0111\u1ec3 kh\u1eb3ng \u0111\u1ecbnh v\u1ecb tr\xed t\xf4n quy\u1ec1n c\u1ee7a m\xecnh. Bi\u1ec3u t\u01b0\u1ee3ng c\u1ee7a s\u1ee9c m\u1ea1nh v\xe0 uy quy\u1ec1n",B.cf)
B.a_L=new A.cs("H\xecnh r\u1ed3ng trong nh\u1eefng kh\xf4ng gian t\xedn ng\u01b0\u1ee1ng c\u1ee7a ng\u01b0\u1eddi Vi\u1ec7t nh\u01b0: ch\xf9a chi\u1ec1n, l\u0103ng t\u1ea9m, mi\u1ebfu th\u1edd\u2026 R\u1ed3ng kh\xf4ng \u0111\u01b0\u1ee3c th\u1edd c\xfang trong \u0111\u1ec1n ch\xf9a nh\u01b0 nh\u1eefng linh v\u1eadt kh\xe1c m\xe0 th\u01b0\u1eddng trong t\u01b0 th\u1ebf n\u1eb1m ch\u1ea7u, cu\u1ed1n quanh c\u1ed9t x\xe2y, n\u1eb1m u\u1ed1n l\u01b0\u1ee3n tr\xean m\xe1i \u0111\xecnh\u2026 H\xecnh \u1ea3nh n\xe0y l\xe0 bi\u1ec3u t\u01b0\u1ee3ng cho s\u1ef1 che ch\u1edf, ph\u1ee5c v\u1ee5, lu\xf4n s\u1eb5n s\xe0ng b\u1ea3o v\u1ec7.",B.cf)
B.a_N=new A.cs("Trong phong th\u1ee7y, r\u1ed3ng l\xe0 linh v\u1eadt h\u1ed9i t\u1ee5 c\xe1c y\u1ebfu t\u1ed1 t\u1ef1 nhi\xean, do \u0111\xf3 \u0111\u01b0\u1ee3c coi nh\u01b0 m\u1ed9t linh v\u1eadt c\u1ee7a s\u1ef1 th\u1ecbnh v\u01b0\u1ee3ng, may m\u1eafn, tr\xed tu\u1ec7, \u0111\u01b0\u1ee3c g\u1eedi g\u1eafm nh\u1eefng \u01b0\u1edbc v\u1ecdng: c\u1ea7u n\u1eafng, c\u1ea7u m\u01b0a, c\u1ea7u ph\u1ed3n th\u1ef1c\u2026 R\u1ed3ng l\xe0 bi\u1ec3u t\u01b0\u1ee3ng c\u1ee7a m\u01b0a thu\u1eadn gi\xf3 h\xf2a, c\u1ee7a ch\xe2n thi\u1ec7n m\u1ef9, \u0111i\u1ec1u t\u1ed1t \u0111\u1eb9p.",B.cf)
B.a_M=new A.cs("R\u1ed3ng l\xe0 m\u1ed9t trong b\u1ed1n linh v\u1eadt mang may m\u1eafn: Long, L\xe2n, Quy, Ph\u01b0\u1ee3ng. R\u1ed3ng \u0111\u1ea1i di\u1ec7n cho t\xednh d\u01b0\u01a1ng, s\u1ee9c m\u1ea1nh c\u1ee7a ng\u01b0\u1eddi \u0111\xe0n \xf4ng. Song h\xe0nh v\u1edbi r\u1ed3ng ch\xednh l\xe0 ph\u01b0\u1ee3ng ho\xe0ng, \u0111\u1ea1i di\u1ec7n cho t\xednh \xe2m, ng\u01b0\u1eddi ph\u1ee5 n\u1eef. H\xecnh \u1ea3nh r\u1ed3ng ph\u01b0\u1ee3ng \u0111\u01b0\u1ee3c bi\u1ebft \u0111\u1ebfn nh\u01b0 m\u1ed9t bi\u1ec3u t\u01b0\u1ee3ng c\u1ee7a s\u1ef1 h\xf2a h\u1ee3p \xe2m d\u01b0\u01a1ng.",B.cf)
B.a77=s([B.a_I,B.a_L,B.a_N,B.a_M],t.Xn)
B.Ve=new A.dH(6,"R\u1ed3ng",B.a77,"assets/bieu-tuong-thang/06-rong.jpg")
B.a_G=new A.cs("C\xe2y \u0111a l\xe0 m\u1ed9t bi\u1ec3u t\u01b0\u1ee3ng v\u0103n ho\xe1 \u0111\u1eb7c tr\u01b0ng c\u1ee7a Vi\u1ec7t Nam g\u1eafn b\xf3 v\u1edbi cu\u1ed9c s\u1ed1ng t\xe2m h\u1ed3n con ng\u01b0\u1eddi t\u1eeb xa x\u01b0a.",B.bf)
B.a_P=new A.cs("C\xe2y \u0111a t\u01b0\u1ee3ng tr\u01b0ng cho s\u1ef1 tr\u01b0\u1eddng t\u1ed3n, s\u1ee9c s\u1ed1ng d\u1ebbo dai. C\xe2y \u0111a c\xf2n \u0111\u1ea1i di\u1ec7n cho h\u1ed9i t\u1ee5 quy\u1ec1n n\u0103ng v\u0169 tr\u1ee5, k\u1ebft n\u1ed1i quy\u1ec1n n\u0103ng tr\u1eddi \u0111\u1ea5t \u0111\u1ec3 che ch\u1edf, ph\xf9 h\u1ed9 cho l\xe0ng x\xf3m, ng\u01b0\u1eddi d\xe2n.",B.bf)
B.a_r=new A.cs("Tr\xean th\u1ef1c t\u1ebf, d\u01b0\u1edbi b\xf3ng c\xe2y \u0110a, con ng\u01b0\u1eddi \u0111\xe3 bao l\u1ea7n b\u1ed9c l\u1ed9 t\xecnh c\u1ea3m, g\u1ea7n g\u0169i nhau trong sinh ho\u1ea1t l\xe0m \u0103n. \u0110\u1ea5y c\u0169ng l\xe0 \u0111\u1ecba ch\u1ec9 h\u1ed9i t\u1ee5 bi\u1ebft bao k\u1ef7 ni\u1ec7m c\u1ee7a c\xe1c th\u1ebf h\u1ec7 ng\u01b0\u1eddi d\xe2n gi\u1eefa v\xf4 v\xe0n c\xe1c m\u1ed1i quan h\u1ec7 v\u1edbi t\u1ef1 nhi\xean v\xe0 x\xe3 h\u1ed9i. Kh\xf4ng ph\u1ea3i ng\u1eabu nhi\xean m\xe0, m\u1ed7i khi \u0111i xa, ng\u01b0\u1eddi ta th\u01b0\u1eddng nh\u1edb v\u1ec1 c\xe2y \u0110a nh\u01b0 nh\u1edb v\u1ec1 qu\xea h\u01b0\u01a1ng, nh\u1edb v\u1ec1 c\u1ed9i ngu\u1ed3n v\u1edbi t\xecnh c\u1ea3m ch\xe2n th\xe0nh, da di\u1ebft.",B.bf)
B.a_E=new A.cs("C\xe2y \u0111a \u0111\xe3 t\u1eeb th\u1ebf gi\u1edbi c\xe2y c\u1ecf t\u1ef1 nhi\xean b\u01b0\u1edbc v\xe0o th\u1ebf gi\u1edbi t\xe2m linh, ho\xe0 nh\u1eadp t\xedn ng\u01b0\u1ee1ng c\u1ed9ng \u0111\u1ed3ng, tr\u1edf th\xe0nh bi\u1ec3u t\u01b0\u1ee3ng cho s\u1ee9c m\u1ea1nh tinh th\u1ea7n c\u1ee7a m\u1ed9t x\xf3m l\xe0ng, l\xe0 n\u01a1i n\u01b0\u01a1ng t\u1ef1a tinh th\u1ea7n v\u1eefng ch\u1eafc cho ch\xfang sinh.",B.bf)
B.a7c=s([B.a_G,B.a_P,B.a_r,B.a_E],t.Xn)
B.Vl=new A.dH(7,"C\xe2y \u0111a, b\u1ebfn n\u01b0\u1edbc",B.a7c,"assets/bieu-tuong-thang/07-cay-da-ben-nuoc.jpg")
B.a_R=new A.cs("T\u1eeb thu\u1edf s\u01a1 khai, khi ng\u01b0\u1eddi Vi\u1ec7t c\u1ed5 \u0111\u1ecbnh c\u01b0 \u1edf c\xe1c \u0111\u1ed3ng b\u1eb1ng ph\xf9 sa m\xe0u m\u1ee1, c\xe2y l\xfaa \u0111\xe3 tr\u1edf th\xe0nh trung t\xe2m c\u1ee7a \u0111\u1eddi s\u1ed1ng kinh t\u1ebf. Nh\u1eafc \u0111\u1ebfn bi\u1ec3u t\u01b0\u1ee3ng c\xe2y l\xfaa l\xe0 nh\u1eafc \u0111\u1ebfn t\xedn ng\u01b0\u1ee1ng n\xf4ng nghi\u1ec7p Vi\u1ec7t Nam. Ng\u01b0\u1eddi Vi\u1ec7t t\u1eeb l\xe2u \u0111\xe3 th\u1edd th\u1ea7n N\xf4ng - v\u1ecb th\u1ea7n \u0111\u01b0\u1ee3c xem l\xe0 ng\u01b0\u1eddi d\u1ea1y d\xe2n tr\u1ed3ng l\xfaa, c\xe0y c\u1ea5y.",B.bf)
B.a_Q=new A.cs("\xdd ngh\u0129a c\u1ee7a c\xe2y l\xfaa kh\xf4ng ch\u1ec9 n\u1eb1m \u1edf nh\u1eefng b\xf4ng l\xfaa v\xe0ng m\xe0 c\xf2n n\u1eb1m \u1edf h\xe0nh tr\xecnh t\u1ea1o n\xean b\xf4ng l\xfaa. \u0110\u1ea7u m\xf9a khi gieo m\u1ea1, nh\xe2n d\xe2n g\u1eedi g\u1eafm \u01b0\u1edbc v\u1ecdng v\u1ec1 m\u01b0a thu\u1eadn gi\xf3 ho\xe0, m\xf9a m\xe0ng b\u1ed9i thu. \u0110\u1ebfn khi m\xf9a l\xfaa ch\xedn v\xe0ng, nh\u1eefng h\u1ea1t g\u1ea1o \u0111\u1ea7u ti\xean \u0111\u01b0\u1ee3c coi l\xe0 \u201ch\u1ea1t ng\u1ecdc tr\u1eddi\u201d, kh\xf4ng \u0111\u01b0\u1ee3c \u0103n ngay m\xe0 \u0111\u01b0\u1ee3c d\xe2ng c\xfang, th\u1ec3 hi\u1ec7n l\xf2ng k\xednh tr\u1ecdng \u0111\u1ed1i v\u1edbi ngu\u1ed3n s\u1ed1ng thi\xeang li\xeang, tri \xe2n tr\u1eddi \u0111\u1ea5t, t\u1ed5 ti\xean \u0111\xe3 ph\xf9 h\u1ed9 cho v\u1ee5 m\xf9a th\xe0nh c\xf4ng.",B.bf)
B.a_y=new A.cs("H\u1ea1t g\u1ea1o c\u1ee7a c\xe2y l\xfaa c\xf2n mang \xfd ngh\u0129a sinh s\xf4i, h\u1ea1nh ph\xfac l\u1ee9a \u0111\xf4i khi \u0111\u01b0\u1ee3c tr\u01b0ng b\xe0y trong c\xe1c nghi l\u1ec5: \u0111\u1ea7y th\xe1ng, th\xf4i n\xf4i v\xe0 c\u01b0\u1edbi h\u1ecfi.",B.bf)
B.a3A=s([B.a_R,B.a_Q,B.a_y],t.Xn)
B.Vm=new A.dH(8,"B\xf4ng l\xfaa ch\xedn",B.a3A,"assets/bieu-tuong-thang/08-bong-lua-chin.jpg")
B.a_A=new A.cs("N\xf3n l\xe1, m\u1ed9t bi\u1ec3u t\u01b0\u1ee3ng v\u0103n ho\xe1 \u0111\u1eb7c tr\u01b0ng c\u1ee7a ng\u01b0\u1eddi Vi\u1ec7t Nam, kh\xf4ng ch\u1ec9 l\xe0 m\u1ed9t m\xf3n \u0111\u1ed3 th\u1eddi trang m\xe0 c\xf2n mang trong m\xecnh nh\u1eefng gi\xe1 tr\u1ecb s\xe2u s\u1eafc v\u1ec1 l\u1ecbch s\u1eed v\xe0 truy\u1ec1n th\u1ed1ng. N\xf3n l\xe1 th\u01b0\u1eddng g\u1eafn li\u1ec1n v\u1edbi h\xecnh \u1ea3nh ng\u01b0\u1eddi n\xf4ng d\xe2n m\u1eabn c\xe1n n\u01a1i \u0111\u1ed3ng ru\u1ed9ng, h\u1ecd \u0111\u1ed9i n\xf3n l\xe1 \u0111\u1ec3 b\u1ea3o v\u1ec7 m\xecnh kh\u1ecfi c\xe1i n\u1eafng oi \u1ea3 v\xe0 nh\u1eefng c\u01a1n m\u01b0a b\u1ea5t ch\u1ee3t. Song, n\xf3n l\xe1 c\xf2n l\xe0 m\u1ed9t v\u1eadt d\u1ee5ng thay th\u1ebf cho chi\u1ebfc qu\u1ea1t tay, gi\xfap t\u1ea1o nh\u1eefng c\u01a1n gi\xf3 m\xe1t khi ngh\u1ec9 gi\u1ea3i lao tr\xean \u0111\u1ed3ng ru\u1ed9ng. Ngo\xe0i ra, v\u1edbi ng\u01b0\u1eddi ph\u1ee5 n\u1eef Vi\u1ec7t, n\xf3n l\xe1 l\xe0m t\xf4n l\xean v\u1ebb d\u1ecbu d\xe0ng, nh\u1eb9 nh\xe0ng, thanh tho\xe1t.",B.bf)
B.a7z=s([B.a_A],t.Xn)
B.Vp=new A.dH(9,"N\xf3n l\xe1",B.a7z,"assets/bieu-tuong-thang/09-non-la.jpg")
B.a_j=new A.cs("Con tr\xe2u l\xe0 v\u1eadt nu\xf4i v\xf4 c\xf9ng quen thu\u1ed9c \u0111\u1ed1i v\u1edbi ng\u01b0\u1eddi d\xe2n Vi\u1ec7t Nam. Xu\u1ea5t hi\u1ec7n v\xe0 g\u1eafn b\xf3 v\u1edbi ng\u01b0\u1eddi n\xf4ng d\xe2n Vi\u1ec7t Nam t\u1eeb r\u1ea5t l\xe2u \u0111\u1eddi, con tr\xe2u c\xf3 \xfd ngh\u0129a r\u1ea5t quan tr\u1ecdng trong \u0111\u1eddi s\u1ed1ng ng\u01b0\u1eddi d\xe2n.",B.bf)
B.a_C=new A.cs("Con tr\xe2u l\xe0 h\xecnh t\u01b0\u1ee3ng bi\u1ec3u tr\u01b0ng cho s\u1ee9c kho\u1ebb d\u1ed3i d\xe0o, th\u1ec3 hi\u1ec7n s\u1ef1 ph\xe1t tri\u1ec3n trong s\u1ea3n xu\u1ea5t n\u1ec1n n\xf4ng nghi\u1ec7p l\xfaa n\u01b0\u1edbc Vi\u1ec7t Nam. Trong n\u1ec1n v\u0103n minh l\xfaa n\u01b0\u1edbc c\u1ee7a \u0111\u1ea5t n\u01b0\u1edbc Vi\u1ec7t Nam t\u1eeb h\xe0ng ngh\xecn n\u0103m, con tr\xe2u theo ng\u01b0\u1eddi n\xf4ng d\xe2n c\u1eaft c\u1ecf, c\xe0y \u0111\u1ea5t,... V\xec th\u1ebf con tr\xe2u c\u0169ng gi\u1ed1ng nh\u01b0 m\u1ed9t ng\u01b0\u1eddi b\u1ea1n g\u1ea7n g\u0169i v\u1edbi con ng\u01b0\u1eddi, \u0111\u1eb7c bi\u1ec7t l\xe0 ng\u01b0\u1eddi n\xf4ng d\xe2n. Con tr\xe2u c\xf2n l\xe0 con v\u1eadt g\u1eafn b\xf3 v\u1edbi gia \u0111\xecnh ng\u01b0\u1eddi n\xf4ng d\xe2n, xu\u1ea5t hi\u1ec7n trong h\xecnh \u1ea3nh h\u1ea1nh ph\xfac c\u1ee7a c\xe1c c\u1eb7p v\u1ee3 ch\u1ed3ng n\xf4ng d\xe2n x\u01b0a trong s\u1ea3n xu\u1ea5t n\xf4ng nghi\u1ec7p.",B.bf)
B.a_K=new A.cs("T\u1eeb xa x\u01b0a, con tr\xe2u v\u1eeba l\xe0 t\xe0i s\u1ea3n v\u1eeba l\xe0 ng\u01b0\u1eddi b\u1ea1n th\xe2n thi\u1ebft v\u1edbi ng\u01b0\u1eddi n\xf4ng d\xe2n, v\xe0 c\u0169ng l\xe0 bi\u1ec3u t\u01b0\u1ee3ng c\u1ee7a s\u1ef1 th\xe0nh \u0111\u1ea1t. Th\xf4ng qua h\xecnh \u1ea3nh con tr\xe2u, ng\u01b0\u1eddi x\u01b0a mu\u1ed1n n\xf3i l\xean vi\u1ec7c lao \u0111\u1ed9ng n\xf4ng nghi\u1ec7p v\xf4 c\xf9ng v\u1ea5t v\u1ea3 \u201cm\u1ed9t n\u1eafng hai s\u01b0\u01a1ng\u201d, \u0111\u1ed3ng th\u1eddi c\xf2n ca ng\u1ee3i t\xednh c\u1ea7n c\xf9, ch\u0103m ch\u1ec9 c\u1ee7a ng\u01b0\u1eddi n\xf4ng d\xe2n Vi\u1ec7t Nam.",B.bf)
B.a3l=s([B.a_j,B.a_C,B.a_K],t.Xn)
B.Vh=new A.dH(10,"Tr\xe2u n\u01b0\u1edbc",B.a3l,"assets/bieu-tuong-thang/10-trau-nuoc.jpg")
B.a_J=new A.cs("N\xe9t \u0111\u1eb9p c\u1ee7a tr\u1ea7u, cau \u0111\xe3 t\u1eeb l\xe2u \u0111\u01b0\u1ee3c \u0111\u01b0a v\xe0o ca dao, d\xe2n ca, l\u1eddi n\xf3i v\xe0 l\u1eddi ca ti\u1ebfng h\xe1t. C\xf3 l\u1ebd b\u1eaft ngu\u1ed3n t\u1eeb s\u1ef1 t\xedch v\u1ec1 \u201cTr\u1ea7u, Cau v\xe0 V\xf4i\u201d \u0111\u01b0\u1ee3c l\u01b0u truy\u1ec1n t\u1eeb th\u1ebf h\u1ec7 n\xe0y sang th\u1ebf h\u1ec7 kh\xe1c b\u1edfi v\u1ebb \u0111\u1eb9p tinh t\u1ebf c\u1ee7a thi\xean nhi\xean trong t\xe2m th\u1ee9c con ng\u01b0\u1eddi, l\xe0 m\u1ed9t \u0111\u1eddi s\u1ed1ng tinh th\u1ea7n b\u1ec1n v\u1eefng v\u1ec1 thi\xean nhi\xean g\u1eafn b\xf3 b\u1ec1n ch\u1eb7t t\u1ea1o n\xean h\u01b0\u01a1ng s\u1eafc cho cu\u1ed9c \u0111\u1eddi, hay t\xecnh c\u1ea3m anh em ho\xe0 thu\u1eadn, ch\u0103m s\xf3c y\xeau th\u01b0\u01a1ng, \u0111\xf9m b\u1ecdc nhau, s\u1ef1 n\u1ed3ng n\xe0n c\u1ee7a ngh\u0129a v\u1ee3 t\xecnh ch\u1ed3ng \u0111\u1eadm \u0111\xe0 s\u1eafc con nh\u01b0 c\xe2u chuy\u1ec7n c\u1ed5 t\xedch \u1ea5y.",B.bf)
B.a_z=new A.cs("\u0110\xe3 kh\xf4ng bi\u1ebft t\u1ef1a l\xfac n\xe0o, n\u01a1i \u0111\xe2u m\xe0 trong t\xe2m th\u1ee9c \u0111\u1eddi s\u1ed1ng ng\u01b0\u1eddi Vi\u1ec7t lu\xf4n tr\xe2n qu\xfd h\xecnh \u1ea3nh tr\u1ea7u cau nh\u01b0 v\u1eady. Mi\u1ebfng tr\u1ea7u mi\u1ebfng cau l\xe0 m\xf3n ngon, l\xe0 th\u1ee9 qu\xfd gi\xe1 trong nh\xe0 d\xf9ng l\xe0m \u201c\u0111\u1ea7u tr\u1ecf ti\u1ebfp kh\xe1ch\u201d. Mi\u1ebfng tr\u1ea7u mi\u1ebfng cau c\xf2n \u0111i v\xe0o trong v\u0103n ho\xe1 c\u1ee7a ng\u01b0\u1eddi Vi\u1ec7t v\u1edbi phong t\u1ee5c nhu\u1ed9m r\u0103ng \u0111en. Mi\u1ebfng tr\u1ea7u mi\u1ebfng cau c\xf2n nh\u01b0 m\u1ed1i t\u01a1 l\xf2ng v\u1ea5n v\u01b0\u01a1ng, m\u1ed9t nh\u1edb, hai th\u01b0\u01a1ng, ba ch\u1edd, b\u1ed1n \u0111\u1ee3i m\u1ed9t m\u1ed1i t\xecnh son; l\xe0 l\u1eddi trai g\xe1i h\u1eb9n h\xf2, m\u1ed9t ngh\u0129a t\xecnh thu\u1ef7 chung, nh\u1eb9 nh\xe0ng, s\xe2u s\u1eafc.",B.bf)
B.a58=s([B.a_J,B.a_z],t.Xn)
B.Vk=new A.dH(11,"Tr\u1ea7u cau",B.a58,"assets/bieu-tuong-thang/11-trau-cau.jpg")
B.a_F=new A.cs("B\xe1nh ch\u01b0ng b\xe1nh gi\u1ea7y l\xe0 m\xf3n \u0103n d\xe2n gian \u0111\u1eb7c tr\u01b0ng c\u1ee7a d\xe2n t\u1ed9c trong nh\u1eefng ng\xe0y \u0111\u1ea7u n\u0103m m\u1edbi. T\u1ee5c g\xf3i b\xe1nh ch\u01b0ng ng\xe0y T\u1ebft \u0111\xe3 tr\u1edf th\xe0nh n\xe9t v\u0103n ho\xe1 truy\u1ec1n th\u1ed1ng c\u1ee7a d\xe2n t\u1ed9c Vi\u1ec7t Nam, \u0111\u01b0\u1ee3c l\u01b0u truy\u1ec1n qua nhi\u1ec1u th\u1ebf h\u1ec7 ng\u01b0\u1eddi Vi\u1ec7t, th\u1ec3 hi\u1ec7n n\xe9t \u0111\u1eb9p c\u1ee7a n\u1ec1n v\u0103n minh l\xfaa n\u01b0\u1edbc. Truy\u1ec1n thuy\u1ebft xa x\u01b0a \u1ea5y v\u1ec1 s\u1ef1 t\xedch chi\u1ebfc b\xe1nh ch\u01b0ng b\xe1nh gi\u1ea7y c\xf2n g\xf3i trong \u0111\xf3 l\xe0 m\u1ed9t n\u1ec1n v\u0103n minh n\xf4ng nghi\u1ec7p l\xfaa n\u01b0\u1edbc ph\xe1t tri\u1ec3n. B\xe1nh ch\u01b0ng ch\xednh l\xe0 s\u1ea3n ph\u1ea9m c\u1ee7a tr\u1ed3ng tr\u1ecdt v\xe0 ch\u0103n nu\xf4i. B\xean ngo\xe0i chi\u1ebfc l\xe1 dong g\xf3i b\xe1nh c\xf3 s\u1eb5n t\u1eeb thi\xean nhi\xean, b\xean trong \u0111\u01b0\u1ee3c ch\u1ebf bi\u1ebfn t\u1eeb ngu\u1ed3n nguy\xean li\u1ec7u n\u1ea5u \u0103n c\u1ed9i r\u1ec5 c\u1ee7a d\xe2n t\u1ed9c: g\u1ea1o n\u1ebfp, \u0111\u1eadu xanh, th\u1ecbt heo - c\xe1c s\u1ea3n ph\u1ea9m t\u1eeb tr\u1ed3ng tr\u1ecdt v\xe0 ch\u0103n nu\xf4i.",B.bf)
B.a_q=new A.cs("Song, b\xe1nh ch\u01b0ng b\xe1nh gi\u1ea7y c\xf2n th\u1ec3 hi\u1ec7n quan ni\u1ec7m c\u1ee7a ng\u01b0\u1eddi d\xe2n Vi\u1ec7t Nam v\u1ec1 v\u0169 tr\u1ee5, nh\xe2n sinh. B\xe1nh ch\u01b0ng \u0111\u1ea1i di\u1ec7n cho \u0111\u1ea5t, th\u1ec3 hi\u1ec7n s\u1ef1 sung t\xfac, \u1ea5m no, c\u0169ng \u0111\u1ea1i di\u1ec7n cho c\xf4ng d\u01b0\u1ee1ng d\u1ee5c sinh th\xe0nh c\u1ee7a cha m\u1eb9. B\xe1nh gi\u1ea7y \u0111\u1ea1i di\u1ec7n cho tr\u1eddi, c\xf3 h\xecnh d\xe1ng tr\xf2n tr\u1ecba, \u0111\u1ea7y \u0111\u1eb7n ch\xednh l\xe0 s\u1ef1 \u0111\u1ee7 \u0111\u1ea7y, tr\u1ecdn v\u1eb9n trong cu\u1ed9c s\u1ed1ng. \u0110\u1ea5t v\xe0 Tr\u1eddi c\u0169ng ch\xednh l\xe0 hai th\u1ee9 nh\xe2n d\xe2n t\xf4n th\u1edd, lu\xf4n bao b\u1ecdc, che ch\u1edf d\xe2n.",B.bf)
